import{_ as n,o as t,c as i,a1 as e}from"./chunks/framework.DxqwKiYY.js";const g="/pelatihan-webgis-big/assets/image1.B9T2wlGZ.png",s="/pelatihan-webgis-big/assets/image2.BwAqIAPJ.png",r="/pelatihan-webgis-big/assets/image3.D3Z0OSPa.png",l="/pelatihan-webgis-big/assets/image4.D2PQL9-Z.png",o="/pelatihan-webgis-big/assets/image.CR0D1jUF.png",p="/pelatihan-webgis-big/assets/image%201.D1Q3wIcQ.png",u="/pelatihan-webgis-big/assets/image7.D2AdqYGj.png",m="/pelatihan-webgis-big/assets/image%202.xfny28Ka.png",k="/pelatihan-webgis-big/assets/image%203.BzX1tUxm.png",b="/pelatihan-webgis-big/assets/image10.Ot-_xgxi.png",d="/pelatihan-webgis-big/assets/image11.T51Nnjm0.png",y="/pelatihan-webgis-big/assets/image12.DYLRNH0F.png",c="/pelatihan-webgis-big/assets/image%204.BqxJLnHT.png",h="/pelatihan-webgis-big/assets/image%205.C86xb7Ag.png",f="/pelatihan-webgis-big/assets/image%206.IegGXPN-.png",_="/pelatihan-webgis-big/assets/image%207.CFMNrbPg.png",G=JSON.parse('{"title":"Styling Layer Dengan Javascript - 1","description":"","frontmatter":{},"headers":[],"relativePath":"Training WebGIS BIG/Modul 2 - Pengembangan Frontend Peta 2D/Styling Layer Dengan Javascript - 1.md","filePath":"Training WebGIS BIG/Modul 2 - Pengembangan Frontend Peta 2D/Styling Layer Dengan Javascript - 1.md"}'),w={name:"Training WebGIS BIG/Modul 2 - Pengembangan Frontend Peta 2D/Styling Layer Dengan Javascript - 1.md"};function j(S,a,L,P,D,v){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="styling-layer-dengan-javascript-1" tabindex="-1">Styling Layer Dengan Javascript - 1 <a class="header-anchor" href="#styling-layer-dengan-javascript-1" aria-label="Permalink to &quot;Styling Layer Dengan Javascript - 1&quot;">​</a></h1><p><strong>Styling Layer Dengan Javascript</strong></p><h2 id="styling-layer-geojson" tabindex="-1"><strong>Styling Layer Geojson</strong> <a class="header-anchor" href="#styling-layer-geojson" aria-label="Permalink to &quot;**Styling Layer Geojson**&quot;">​</a></h2><ol><li><p>Pada tahap pertama, lakukan styling pada file <strong>Geojson.jsx</strong> untuk mengatur ukuran icon pada variabel <strong>const markerIcon.</strong> Pertama lakukan styling untuk mengatur ukuran icon dengan menggunakan variabel <strong>iconSize</strong> kemudian tentukan ukuran lebar dan tingginya dalam [ ].</p><p><img src="'+g+'" alt=""></p></li><li><p>Selanjutnya tambahkan fungsi untuk mengatur mengatur ukuran titik sebenarnya pada peta sehingga titik sebenarnya berada pada posisi center marker. Gunakan fungsi i<strong>conAnchor</strong> kemudian tambahkan ukurannya.</p><p><img src="'+s+'" alt=""></p></li><li><p>Kemudian tambahkan fungsi berupa <strong>popupAnchor</strong> untuk menampilkan posisi popup terhadap marker.</p><p><img src="'+r+'" alt=""></p></li><li><p>Kemudian buat fungsi dibawah variabel markerIcon yang akan digunakan untuk mengatur styling jika data geojson dalam bentuk polygon dengan cara membuat <strong>function getPolygonstyle</strong> serta tambahkan parameter <strong>feature</strong> untuk mengambil tampilan layer.</p><p><img src="'+l+'" alt=""></p></li><li><p>Selanjutnya dalam fungsi tersebut, tambahkan variabel untuk mengambil informasi berupa kategori yang akan dijadikan parameter untuk melakukan styling.</p><p><img src="'+o+'" alt="image.png"></p></li><li><p>Tahap berikutnya buat kondisi kategori menggunakan fungsi <strong>if</strong> kemudian tentukan parameter yang digunakan pada kategorinya, seperti pada script ini mengambil layer dengan kategori <strong>landmark</strong>.</p><p><img src="'+p+'" alt="image.png"></p></li><li><p>Selanjutnya pada fungsi kondisional <strong>if</strong> tersebut buat fungsi <strong>return</strong> yang akan mengembalikan layer sesuai dengan styling yang akan dibuat nantinya.</p><p><img src="'+u+'" alt=""></p></li><li><p>Selanjutnya didalam <strong>return</strong> buat fungsi untuk warna dengan <strong>color</strong>, kemudian tambahkan fungsi untuk mengatur ketebalan garis dengan <strong>weight</strong>, kemudian tambahkan fungsi untuk mengatur warna bagian dalam dengan <strong>fillColor</strong> serta transparansi warna dengan <strong>fillOpacity</strong>.</p><p><img src="'+m+'" alt="image.png"></p></li><li><p>Selanjutnya buat kondisi untuk layer jika memiliki kategori berupa pemerintahan dengan fungsi kondisional <strong>if</strong>.</p><p><img src="'+k+'" alt="image.png"></p></li><li><p>Kemudian buat fungsi <strong>return</strong> jika layer tidak terdapat dalam dua kategori tersebut, styling layernya akan dibuat menjadi warna abu-abu.</p><p><img src="'+b+'" alt=""></p></li><li><p>Selanjutnya pada fungsi c<strong>onst geojsonLayer</strong> yang sudah ada sebelumnya, tambahkan fungsi style dan buat return berupa <strong>getPolygonsStyle</strong> untuk mengambil styling yang telah dibuat.</p><p><img src="'+d+'" alt=""></p></li><li><p>Hasil akhir dari styling geojson layer yaitu sebagai berikut ini.</p><p><img src="'+y+'" alt=""></p></li></ol><h2 id="styling-layer-kml" tabindex="-1"><strong>Styling Layer KML</strong> <a class="header-anchor" href="#styling-layer-kml" aria-label="Permalink to &quot;**Styling Layer KML**&quot;">​</a></h2><ol><li><p>Tahap pertama buka file <strong>Kml.jsx</strong> kemudian pada fungsi script yang digunakan untuk menerima dan mengolah Kml yaitu pada fungsi berupa <strong>.then(function(kmlText)</strong> buat fungsi untuk mengakses objek dalam kml melalui <strong>kmlLayer.eachLayer(function(layer)</strong>.</p><p><img src="'+c+'" alt="image.png"></p></li><li><p>Selanjutnya buat kondisional <strong>if</strong> untuk menganalisis apakah layer bisa diberi style atau tidak.</p><p><img src="'+h+'" alt="image.png"></p></li><li><p>Tahap berikutnya jika file dapat diberikan style, maka buat variabel fungsi untuk warna dengan <strong>color</strong>, kemudian tambahkan fungsi untuk mengatur ketebalan garis dengan <strong>weight</strong>, kemudian tambahkan fungsi untuk mengatur warna bagian dalam dengan <strong>fillColor</strong> serta transparansi warna dengan <strong>fillOpacity</strong>.</p><p><img src="'+f+'" alt="image.png"></p></li><li><p>Hasil tampilan styling layer kml dengan menggunakan warna biru sebagai warna stylenya dapat dilihat pada gambar berikut ini.</p><p><img src="'+_+'" alt="image.png"></p></li></ol>',6)])])}const I=n(w,[["render",j]]);export{G as __pageData,I as default};
